struct DataSource {
  virtual std::optional<Customer> find(const std::string& id) = 0;
  virtual ~DataSource() = default;
};

Order enrich(const Order& in, DataSource& src) {
  Order out = in;
  if (auto c = src.find(in.customer_id)) {   // absent -> leave the message as it is
    out.customer_name = c->name; out.region = c->region;
  }
  return out;
}

